mapper.select:
SELECT br.borrow_id, br.user_id, u.user_no, u.user_name, br.book_id, b.book_name, b.isbn, br.borrow_time, br.due_return_time, br.actual_return_time, br.borrow_status, CASE br.borrow_status WHEN 0 THEN 'not_returned' WHEN 1 THEN 'returned' WHEN 2 THEN 'overdue' END AS borrow_status_text, CASE WHEN br.actual_return_time IS NULL AND br.due_return_time < CURRENT_TIMESTAMP THEN DATEDIFF(CURRENT_DATE, DATE(br.due_return_time)) ELSE 0 END AS overdue_days FROM borrow_record br JOIN sys_user u ON br.user_id = u.user_id JOIN book b ON br.book_id = b.book_id
AND br.user_id = #{userId}
AND br.borrow_status = #{status}
ORDER BY br.borrow_time DESC, br.borrow_id DESC

SELECT br.borrow_id, br.user_id, u.user_no, u.user_name, br.book_id, b.book_name, b.isbn, br.borrow_time, br.due_return_time, br.actual_return_time, br.borrow_status, CASE br.borrow_status WHEN 0 THEN 'not_returned' WHEN 1 THEN 'returned' WHEN 2 THEN 'overdue' END AS borrow_status_text, CASE WHEN br.actual_return_time IS NULL AND br.due_return_time < CURRENT_TIMESTAMP THEN DATEDIFF(CURRENT_DATE, DATE(br.due_return_time)) ELSE 0 END AS overdue_days FROM borrow_record br JOIN sys_user u ON br.user_id = u.user_id JOIN book b ON br.book_id = b.book_id
AND br.user_id = #{userId}
AND br.borrow_status = #{status}
ORDER BY br.borrow_time DESC, br.borrow_id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM borrow_record br


        AND br.user_id = #{userId}


        AND br.borrow_status = #{status}
